INSERT INTO public.kri_items (id, org_id, kri_id, name, description, risk_category, formula, data_source, risk_owner, note, unit, frequency, current_value, previous_value, trend, threshold_green, threshold_amber, threshold_red, current_status, appetite_limit, appetite_breach)
VALUES
  ('a5000000-0000-4000-8000-000000000001', '00000000-0000-0000-0000-000000000001', 'RAS-001', 'Negative and image-damaging information published in the media', 'The Bureau applies a low-tolerance principle regarding the impact of negative news, information, and commentary published in the mass media. A zero-tolerance risk strategy has been chosen for content that creates very high reputational risks, and the monitoring, assessment, and prompt response to such cases are carried out in line with the company’s communications and risk management procedures. In line with the risk acceptance policy, graded (except for high and very high risks) and short-term negative information may be accepted within the established management mechanisms.', 'reputation', '(Negative news, information, and comments published in the mass media during the period / Total media items during the period) x100%', 'Media monitoring system', 'Public Relations and Communications Division', NULL, 'Percent', 'monthly', 0, 0, 'flat', '<4%', '4%-5%', '>5%', 'green', 'Low', false),
  ('a5000000-0000-4000-8000-000000000002', '00000000-0000-0000-0000-000000000001', 'RAS-002', 'Recovery Time (RTO)', 'The Bureau has a low risk appetite for service interruptions in critical business processes and does not tolerate a per-incident service recovery time exceeding 2 hours.', 'information_security', 'Total downtime that occurred in the system during the period and the recovery time for that downtime', 'Information security tools', 'Chief Information Officer', NULL, 'Hours', 'monthly', 0, 0, 'flat', '<1', '1-2', '>2', 'green', 'Low', false),
  ('a5000000-0000-4000-8000-000000000003', '00000000-0000-0000-0000-000000000001', 'RAS-003', 'Recovery Point Objective (RPO)', 'The organization shows zero tolerance for data loss in critical information systems. Under the zero-tolerance requirement, any value greater than 0 is treated as a limit breach.', 'information_security', 'The maximum acceptable data-loss window when an event (interruption, system failure, cyber incident, etc.) occurs during the period (in line with the backup strategy)', 'Information security tools', 'Chief Information Officer', NULL, 'Hours', 'monthly', 0, 0, 'flat', '', '', '>0', 'green', 'Low', false),
  ('a5000000-0000-4000-8000-000000000004', '00000000-0000-0000-0000-000000000001', 'RAS-004', 'Transfer of sensitive data (DLP)', 'The transfer of sensitive data (data considered confidential that is not in the public-information category, personal data, and insurance data) to other parties is not permitted. Under the zero-tolerance requirement, any value greater than 0 is treated as a limit breach.', 'information_security', 'Attempts and occurrences during the period (the number of leaks/transfers of sensitive and confidential data by physical means or electronically)', 'Information security tools', 'Chief Information Security Officer', NULL, 'Times', 'monthly', 0, 0, 'flat', '', '', '>0', 'green', 'Low', false),
  ('a5000000-0000-4000-8000-000000000005', '00000000-0000-0000-0000-000000000001', 'RAS-005', 'Interruptions in sector-affecting business processes', 'During the period, the total number of unplanned outages in critical systems affecting the sector within the business process must not exceed 4.', 'information_security', 'Number of unplanned outages in the business process during the period', 'Information security tools', 'Chief Information Officer', NULL, 'Times', 'monthly', 0, 0, 'flat', '≤1', '2-3', '≥4', 'green', 'Low', false),
  ('a5000000-0000-4000-8000-000000000006', '00000000-0000-0000-0000-000000000001', 'RAS-006', 'Remediation of risks and events arising during the period and of audit findings', 'The Bureau applies a low-tolerance principle to the number and percentage of all very high and high events overdue for remediation during the period. When the percentage of events, risks, and audit findings rated very high and high in any period exceeds the established threshold, prompt investigation and preventive measures are carried out and immediately escalated. Minimal, low, and medium events, audit findings, and risks are tracked and managed within the established procedures.', 'compliance', '(High and very high rated risks, events, and audit findings overdue for remediation during the period / High and very high rated risks, events, and audit findings awaiting resolution during the period) x100%', 'JIRA', 'Risk Management Division', NULL, 'Percent', 'quarterly', 0.005, 0.0075, 'down', '<5%', '5%-15%', '>15%', 'green', 'Low', false),
  ('a5000000-0000-4000-8000-000000000007', '00000000-0000-0000-0000-000000000001', 'RAS-007', 'Unanswered Calls', 'To ensure the continuity of customer service, the level of unanswered calls must not exceed 10%. Values above 10% require immediate corrective action.', 'compliance', '(Unanswered calls during the period / Total incoming calls during the period) x100%', 'Complaint/Incident registration system', 'Operations Department', 'In January the missed-call indicator reached 8% and entered the warning zone. It was escalated with the structure and the Executive Director was informed. Meetings were held and the action plan was executed. The limits for missed calls were reviewed and reflected in the procedure.', 'Percent', 'monthly', 0.0078, 0.0078, 'flat', '<5%', '5%-10%', '>10%', 'green', 'Low', false),
  ('a5000000-0000-4000-8000-000000000008', '00000000-0000-0000-0000-000000000001', 'RAS-008', 'Employee turnover', 'The organization aims to keep employee turnover at a manageable level and, taking the natural variability of the labor market into account, accepts employee losses of up to 20%. However, because an excessive rise in turnover negatively affects operational stability, knowledge continuity, and service quality within the organization, this indicator is actively monitored within the risk appetite, and management measures are taken if the established limits are exceeded.', 'operational', '(Number of employees who left during the period / 12-month average headcount) x100%', 'ITSM, 1C ERP', 'Human Resources Division', NULL, 'Percent', 'monthly', 0.0167, 0, 'up', '<10%', '10%-20%', '>20%', 'green', 'Medium', false),
  ('a5000000-0000-4000-8000-000000000009', '00000000-0000-0000-0000-000000000001', 'RAS-009', 'Critical employee turnover', 'The Bureau applies a low-tolerance principle to employee turnover during the period. When the percentage of critical employees leaving during the period exceeds the established threshold, the Human Resources Committee immediately investigates the causes and implements appropriate corrective measures.', 'operational', '(Number of critical employees who left during the period / 12-month average number of critical employees) x100%', 'ITSM, 1C ERP', 'Human Resources Division', NULL, 'Percent', 'monthly', 0, 0, 'flat', '<5%', '5%-10%', '>10%', 'green', 'Low', false),
  ('a5000000-0000-4000-8000-000000000010', '00000000-0000-0000-0000-000000000001', 'RAS-010', 'Operational losses', 'The company has a low risk appetite for operational losses. The amount and frequency of operational losses must be kept within the established limits, recurring events must be minimized, and all significant operational events must be investigated in a timely manner with corrective measures implemented. The company applies zero tolerance to operational losses arising from internal-control deficiencies, fraud, and serious process violations.', 'operational', 'Total amount of operational losses recorded during the period', '1C ERP', 'Finance Division', NULL, 'AZN', 'annual', 0, 0, 'flat', '<10000', '10000-100 000', '>100 000', 'green', 'Medium', false),
  ('a5000000-0000-4000-8000-000000000011', '00000000-0000-0000-0000-000000000001', 'RAS-011', 'Open currency position', 'A low-tolerance principle is applied to the difference between currency assets and liabilities. If the difference between currency assets and liabilities exceeds the established threshold during the period, risk management measures are activated immediately.', 'financial', '(Net open currency position / Capital) x100%', '1C ERP', 'Finance Division', 'As the organization has no regulatory capital, total capital is used as the basis for the calculation.', 'Percent', 'annual', NULL, NULL, 'flat', '<5%', '5–10%', '>10%', 'green', 'Low', false),
  ('a5000000-0000-4000-8000-000000000012', '00000000-0000-0000-0000-000000000001', 'RAS-012', 'Liquidity shortfall', 'The company aims to hold sufficient high-quality liquid assets to meet its short-term liquidity obligations fully and on time. The company does not accept the liquidity ratio falling below the established minimum level (100%), and in such cases a liquidity recovery plan is triggered immediately.', 'financial', 'LCR = (HQLA / Net Cash Outflow, 30 days) x100% Liquidity Coverage Ratio = (High-quality liquid assets / Total net cash outflow over the next 30 calendar days) x 100%', '1C ERP', 'Finance Division', NULL, 'Percent', 'annual', 494.941416898454, 512.271054565941, 'down', '>120%', '120%-100%', '<100%', 'green', 'Low', false),
  ('a5000000-0000-4000-8000-000000000013', '00000000-0000-0000-0000-000000000001', 'RAS-013', 'Expected credit loss on the investment portfolio', 'When managing its investment portfolio, the Bureau prioritizes keeping portfolio risk to a minimum and has drawn up its investment policy conservatively.', 'financial', '(ECL (allowance for credit losses) balance / Total investment portfolio) x100%', '1C ERP', 'Finance Division', NULL, 'Percent', 'annual', 0.0044, 0.0044, 'flat', '<1%', '1-2%', '>2%', 'green', 'Low', false),
  ('a5000000-0000-4000-8000-000000000014', '00000000-0000-0000-0000-000000000001', 'RAS-014', 'Reserve Adequacy', 'The Bureau does not accept a reserve shortfall.', 'financial', 'Reserve Adequacy Ratio = (Technical reserves of the Guarantee Fund / Expected liabilities) ​x100%', 'Database', 'Actuary', NULL, 'Percent', 'annual', NULL, NULL, 'flat', '>110%', '100–110%', '<100%', 'green', 'Low', false),
  ('a5000000-0000-4000-8000-000000000015', '00000000-0000-0000-0000-000000000001', 'RAS-015', 'Stress resilience of the Guarantee Fund', 'At any time, the Fund must maintain the financial resilience to meet the resolution rules and all legally approved statutory obligations in a scenario where at least the single largest participating insurer fails to meet its obligations. As a result of the stress test, the coverage ratio must not fall below 100%.', 'financial', '(Available Guarantee Fund / Liability required to be paid by the Fund under the stress scenario) x100%', 'Database', 'Actuary', NULL, 'Percent', 'annual', NULL, NULL, 'flat', '>110%', '100%-110%', '<100%', 'green', 'Low', false),
  ('a5000000-0000-4000-8000-000000000016', '00000000-0000-0000-0000-000000000001', 'RAS-016', 'Liquidity of the Guarantee Fund', 'Liquid assets must make up at least 5% of the reserves for the compulsory insurance market so that short-term payment obligations are met without delay.', 'financial', '(Liquid assets / Market reserve for compulsory insurance) x100%', 'Database', 'Actuary', NULL, 'Percent', 'annual', NULL, NULL, 'flat', '>10%', '5%-10%', '<5%', 'green', 'Low', false),
  ('a5000000-0000-4000-8000-000000000017', '00000000-0000-0000-0000-000000000001', 'RAS-017', 'Guarantee Fund coverage of the IBNR reserve', 'The ratio of the incurred-but-not-reported losses (IBNR) reserve to the market reserve must be kept within the range determined by actuarial calculations, at a 100% limit. Deviation from this range requires re-assessment of the reserves.', 'financial', '(Guarantee Fund resources / IBNR reserve) x100%', 'Database', 'Actuary', NULL, 'Percent', 'annual', NULL, NULL, 'flat', '>110%', '100%-110%', '<100%', 'green', 'Medium', false),
  ('a5000000-0000-4000-8000-000000000018', '00000000-0000-0000-0000-000000000001', 'RAS-018', 'Market coverage of the Guarantee Fund', 'The Fund’s financial resources must cover at least 5% of the reserves formed for the compulsory insurance market. The indicator falling below 5% is treated as a breach of the risk limit.', 'financial', '(Fund resources / Market reserve for compulsory insurance) x100%', 'Database', 'Actuary', NULL, 'Percent', 'annual', NULL, NULL, 'flat', '>15%', '5%-15%', '<5%', 'green', 'Low', false)
ON CONFLICT (id) DO UPDATE SET
  org_id = EXCLUDED.org_id,
  kri_id = EXCLUDED.kri_id,
  name = EXCLUDED.name,
  description = EXCLUDED.description,
  risk_category = EXCLUDED.risk_category,
  formula = EXCLUDED.formula,
  data_source = EXCLUDED.data_source,
  risk_owner = EXCLUDED.risk_owner,
  note = EXCLUDED.note,
  unit = EXCLUDED.unit,
  frequency = EXCLUDED.frequency,
  current_value = EXCLUDED.current_value,
  previous_value = EXCLUDED.previous_value,
  trend = EXCLUDED.trend,
  threshold_green = EXCLUDED.threshold_green,
  threshold_amber = EXCLUDED.threshold_amber,
  threshold_red = EXCLUDED.threshold_red,
  current_status = EXCLUDED.current_status,
  appetite_limit = EXCLUDED.appetite_limit,
  appetite_breach = EXCLUDED.appetite_breach;

SELECT kri_id, name, risk_category, unit, appetite_limit, current_status
  FROM public.kri_items WHERE kri_id LIKE 'RAS-%' ORDER BY kri_id;
